t.script:
function dismissPortalAutoToast() {
    const toast = document.getElementById('portalAutoToast');
    if (toast) {
        toast.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(-15px)';
        setTimeout(function() { if (toast && toast.parentNode) toast.parentNode.removeChild(toast); }, 400);
    }
    if (window.history.replaceState) {
        const url = new URL(window.location.href);
        url.searchParams.delete('saved');
        url.searchParams.delete('deleted');
        window.history.replaceState({}, document.title, url.pathname + (url.search ? url.search : ''));
    }
}
setTimeout(dismissPortalAutoToast, 3500);

function filterSchoolsTable() {
    const input = document.getElementById('schoolSearchInput');
    const query = (input ? input.value : '').toLowerCase();
    const rows = document.querySelectorAll('#portalSchoolsTable tbody tr.school-row');
    rows.forEach(function(row) {
        const text = row.textContent.toLowerCase();
        row.style.display = text.includes(query) ? '' : 'none';
    });
}

function dismissSchoolProfileToast() {
    const toast = document.getElementById('schoolProfileToast');
    if (toast) {
        toast.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(-15px)';
        setTimeout(function() { if (toast && toast.parentNode) toast.parentNode.removeChild(toast); }, 400);
    }
    if (window.history.replaceState) {
        const url = new URL(window.location.href);
        url.searchParams.delete('saved');
        url.searchParams.delete('action_type');
        window.history.replaceState({}, document.title, url.pathname + (url.search ? url.search : ''));
    }
}
setTimeout(dismissSchoolProfileToast, 3500);

//
document.addEventListener("DOMContentLoaded", function () {
    const calendarEl = document.getElementById("portalFullCalendar");
    if (!calendarEl || typeof FullCalendar === "undefined") {
        return;
    }

    const currentPeriodTitle = document.getElementById("calCurrentPeriodTitle");

    let initialEvents = [];
    try {
        const rawEvents = document.getElementById("portalInitialCalendarEvents")?.textContent;
        if (rawEvents) {
            initialEvents = JSON.parse(rawEvents);
        }
    } catch (e) {
        console.error("Error parsing initial events:", e);
    }

    const calendar = new FullCalendar.Calendar(calendarEl, {
        initialView: "dayGridMonth",
        headerToolbar: false,
        height: "auto",
        aspectRatio: 1.5,
        nowIndicator: true,
        editable: false,
        selectable: true,
        dayMaxEvents: 3,
        events: function (fetchInfo, successCallback, failureCallback) {
            fetch("/portal/calendar/events?start=" + encodeURIComponent(fetchInfo.startStr) + "&end=" + encodeURIComponent(fetchInfo.endStr))
                .then(res => {
                    if (!res.ok) throw new Error("API not available");
                    return res.json();
                })
                .then(data => successCallback(data))
                .catch(err => {
                    successCallback(initialEvents);
                });
        },
        datesSet: function (info) {
            if (currentPeriodTitle) {
                currentPeriodTitle.textContent = info.view.title;
            }
            renderMiniCalendar(calendar.getDate());
        },
        eventClick: function (info) {
            info.jsEvent.preventDefault();
            showEventDetails(info.event);
        },
        select: function (info) {
            openNewEventModal(info.startStr, info.endStr, info.allDay);
        }
    });

    calendar.render();

    // Navigation controls
    document.getElementById("btnCalPrev")?.addEventListener("click", () => calendar.prev());
    document.getElementById("btnCalNext")?.addEventListener("click", () => calendar.next());
    document.getElementById("btnCalToday")?.addEventListener("click", () => calendar.today());

    // Scale Selector Buttons
    document.querySelectorAll(".btn-cal-scale").forEach(function (btn) {
        btn.addEventListener("click", function () {
            document.querySelectorAll(".btn-cal-scale").forEach(b => b.classList.remove("active"));
            this.classList.add("active");
            const view = this.getAttribute("data-view");
            if (view) {
                calendar.changeView(view);
            }
        });
    });

    // Side panel toggle
    const toggleBtn = document.getElementById("btnToggleSidePanel");
    const sidePanel = document.getElementById("portalCalSidePanel");
    const mainCol = document.getElementById("portalCalMainCol");
    toggleBtn?.addEventListener("click", function () {
        if (sidePanel) {
            if (sidePanel.classList.contains("d-none")) {
                sidePanel.classList.remove("d-none");
                mainCol.className = "col-lg-9 col-12";
            } else {
                sidePanel.classList.add("d-none");
                mainCol.className = "col-12";
            }
            calendar.updateSize();
        }
    });

    // Search & Filter
    const searchInput = document.getElementById("calSearchInput");
    searchInput?.addEventListener("input", function (e) {
        const query = e.target.value.toLowerCase().trim();
        document.querySelectorAll(".fc-event").forEach(function (el) {
            const text = el.textContent.toLowerCase();
            el.style.display = (!query || text.includes(query)) ? "" : "none";
        });
    });

    // Detail Modal
    const detailModalEl = document.getElementById("calendarEventDetailModal");
    const bsDetailModal = detailModalEl && window.bootstrap ? new window.bootstrap.Modal(detailModalEl) : null;

    function showEventDetails(ev) {
        if (!detailModalEl) return;
        document.getElementById("detailModalTitle").textContent = ev.title;

        const props = ev.extendedProps || {};
        const startStr = ev.start ? ev.start.toLocaleString() : "";
        const endStr = ev.end ? ev.end.toLocaleString() : "";
        document.getElementById("detailModalTime").textContent = startStr + (endStr ? " - " + endStr : "");

        const locWrap = document.getElementById("detailModalLocationWrap");
        const locEl = document.getElementById("detailModalLocation");
        if (props.location) {
            locWrap.style.display = "block";
            locEl.textContent = props.location;
        } else {
            locWrap.style.display = "none";
        }

        const videoWrap = document.getElementById("detailModalVideoWrap");
        const videoBtn = document.getElementById("detailModalVideoBtn");
        if (props.videocall_location) {
            videoWrap.style.display = "block";
            videoBtn.href = props.videocall_location;
        } else {
            videoWrap.style.display = "none";
        }

        const attWrap = document.getElementById("detailModalAttendeesWrap");
        const attList = document.getElementById("detailModalAttendeesList");
        attList.innerHTML = "";
        if (props.attendees && props.attendees.length > 0) {
            attWrap.style.display = "block";
            props.attendees.forEach(name => {
                const badge = document.createElement("span");
                badge.className = "badge bg-light text-dark border me-1 mb-1 p-2";
                badge.textContent = name;
                attList.appendChild(badge);
            });
        } else {
            attWrap.style.display = "none";
        }

        const descWrap = document.getElementById("detailModalDescWrap");
        const descEl = document.getElementById("detailModalDesc");
        if (props.description) {
            descWrap.style.display = "block";
            descEl.textContent = props.description;
        } else {
            descWrap.style.display = "none";
        }

        const delBtn = document.getElementById("detailModalDeleteBtn");
        if (delBtn) {
            delBtn.onclick = function () {
                if (confirm("Are you sure you want to cancel this meeting?")) {
                    fetch("/portal/calendar/event/delete", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ params: { event_id: ev.id } })
                    }).then(r => r.json()).then(res => {
                        if (res.result && res.result.success) {
                            bsDetailModal?.hide();
                            calendar.refetchEvents();
                        } else {
                            alert(res.result?.error || "Error deleting event");
                        }
                    });
                }
            };
        }

        bsDetailModal?.show();
    }

    // New Event Modal
    const newModalEl = document.getElementById("calendarNewEventModal");
    const bsNewModal = newModalEl && window.bootstrap ? new window.bootstrap.Modal(newModalEl) : null;

    function openNewEventModal(startStr, endStr, allDay) {
        if (!newModalEl) return;
        document.getElementById("calendarNewEventForm")?.reset();

        const startInput = document.getElementById("newEventStart");
        const endInput = document.getElementById("newEventEnd");
        const allDayInput = document.getElementById("newEventAllDay");

        if (startInput && startStr) {
            startInput.value = startStr.substring(0, 16);
        }
        if (endInput && endStr) {
            endInput.value = endStr.substring(0, 16);
        }
        if (allDayInput) {
            allDayInput.checked = Boolean(allDay);
        }
        bsNewModal?.show();
    }

    document.getElementById("btnNewCalendarEvent")?.addEventListener("click", function () {
        const todayStr = new Date().toISOString().substring(0, 10);
        openNewEventModal(todayStr + "T10:00", todayStr + "T11:00", false);
    });

    document.getElementById("btnSaveNewEvent")?.addEventListener("click", function () {
        const name = document.getElementById("newEventTitle")?.value;
        const start = document.getElementById("newEventStart")?.value;
        const stop = document.getElementById("newEventEnd")?.value;
        const allday = document.getElementById("newEventAllDay")?.checked;
        const location = document.getElementById("newEventLocation")?.value;
        const videocall_location = document.getElementById("newEventVideoUrl")?.value;
        const description = document.getElementById("newEventDesc")?.value;

        if (!name || !start) {
            alert("Please enter meeting title and start time.");
            return;
        }

        fetch("/portal/calendar/event/create", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                params: {
                    name: name,
                    start: start,
                    stop: stop,
                    allday: allday,
                    location: location,
                    videocall_location: videocall_location,
                    description: description
                }
            })
        }).then(r => r.json()).then(res => {
            if (res.result && res.result.success) {
                bsNewModal?.hide();
                calendar.refetchEvents();
            } else {
                alert(res.result?.error || "Error scheduling meeting");
            }
        });
    });

    // Mini Calendar Datepicker
    let miniCalDate = new Date();
    function renderMiniCalendar(targetDate) {
        const miniContainer = document.getElementById("portalMiniCalendarBody");
        const miniTitle = document.getElementById("miniCalTitle");
        if (!miniContainer || !miniTitle) return;

        if (targetDate) {
            miniCalDate = new Date(targetDate);
        }

        const year = miniCalDate.getFullYear();
        const month = miniCalDate.getMonth();
        const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
        miniTitle.textContent = monthNames[month] + " " + year;

        const firstDay = new Date(year, month, 1).getDay();
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const today = new Date();

        let html = '<table class="mini-cal-table"><thead><tr>';
        ['Su','Mo','Tu','We','Th','Fr','Sa'].forEach(d => html += '<th>' + d + '</th>');
        html += '</tr></thead><tbody><tr>';

        for (let i = 0; i < firstDay; i++) {
            html += '<td class="other-month"></td>';
        }

        for (let day = 1; day <= daysInMonth; day++) {
            const isToday = (today.getFullYear() === year && today.getMonth() === month && today.getDate() === day);
            const dateStr = year + "-" + String(month + 1).padStart(2, '0') + "-" + String(day).padStart(2, '0');
            html += '<td class="' + (isToday ? 'today' : '') + '" data-date="' + dateStr + '">' + day + '</td>';
            if ((firstDay + day) % 7 === 0 && day !== daysInMonth) {
                html += '</tr><tr>';
            }
        }
        html += '</tr></tbody></table>';
        miniContainer.innerHTML = html;

        miniContainer.querySelectorAll("td[data-date]").forEach(td => {
            td.addEventListener("click", function () {
                const d = this.getAttribute("data-date");
                if (d) {
                    calendar.gotoDate(d);
                }
            });
        });
    }

    document.getElementById("btnMiniPrev")?.addEventListener("click", function () {
        miniCalDate.setMonth(miniCalDate.getMonth() - 1);
        renderMiniCalendar();
    });
    document.getElementById("btnMiniNext")?.addEventListener("click", function () {
        miniCalDate.setMonth(miniCalDate.getMonth() + 1);
        renderMiniCalendar();
    });

    renderMiniCalendar(calendar.getDate());
});
//
